(() => {
  const A=window.DEMO,U=window.DemoUI,D=window.TaskDetails,$=s=>document.querySelector(s),esc=A.esc;let scope='week',tagFilter='all';document.body.classList.add('review-screen');
  const requested=new URLSearchParams(location.search).get('task');if(requested&&A.effectiveTasks().some(t=>t.id===requested))selected=requested;
  if(A.completed().some(t=>t.id===selected)&&!A.weekTasks(7).some(t=>t.id===selected)){scope='completed';tagFilter='confirmed';}
  const period=$('.head-actions .secondary:nth-child(2)');const picker=document.createElement('label');picker.className='review-week-picker';picker.innerHTML='<span>검토 주차</span><select id="review-week" aria-label="검토 주차">'+Array.from({length:16},(_,i)=>'<option value="'+(i+1)+'" '+(i===6?'selected':'disabled')+'>W'+(i+1)+(i===6?' · 02.16 – 02.22':' · 시연 미제공')+'</option>').join('')+'</select>';$('.head-actions').replaceChildren(picker);
  const photo=(src,label,id='')=>'<figure class="photo"><img '+(id?'id="'+id+'" ':'')+'src="'+esc(src)+'" alt="'+esc(label)+'"><figcaption><strong>'+esc(label)+'</strong><span>'+([window.DEMO_DATA.photos.wallBefore,window.DEMO_DATA.photos.wallAfter,window.DEMO_DATA.photos.wallOverlay].includes(src)?'가상 사진 · 분석 예시':'AI 생성 시연 사진')+'</span></figcaption></figure>';
  render=()=>{
    const s=A.read(),weekly=A.weekTasks(7),completed=A.completed(),baseRows=scope==='week'?weekly:completed;
    const definitions=[['all','전체','neutral'],['request','완료 확인 요청','request'],['confirmed','완료 확인','confirmed'],['planned','계획 작업','neutral'],['observation','AI 관측 검토','neutral'],['extension','추가 기간 요청','amber'],['late','일정 확인 필요','amber'],['rejected','반려','amber'],['observed','관측 결과 수락','confirmed'],['accepted','검토 수락','confirmed'],['pending','증빙 검토 대기','neutral']];
    const counts=Object.fromEntries(definitions.map(([key])=>[key,key==='all'?baseRows.length:baseRows.filter(t=>D.status(A.taskInfo(t.id)).key===key).length]));if(!counts[tagFilter])tagFilter='all';
    const rows=baseRows.filter(t=>tagFilter==='all'||D.status(A.taskInfo(t.id)).key===tagFilter);if(!rows.some(t=>t.id===selected))selected=rows[0]?.id;
    const queue=$('.queue');queue.innerHTML='<div class="queue-title">'+(scope==='week'?'제7주 작업':'전체 완료 이력')+'<span class="badge">'+rows.length+'</span></div><div class="review-scope"><button data-scope="week" class="'+(scope==='week'?'active':'')+'">이번 주 '+weekly.length+'</button><button data-scope="completed" class="'+(scope==='completed'?'active':'')+'">완료 이력 '+completed.length+'</button></div><div class="queue-filter">'+(scope==='week'?'완료된 작업도 선택해서 이력을 확인합니다.':'W1~7의 완료 확인 기록을 모아 봅니다.')+'</div><div id="task-list">'+rows.map(t=>{const i=A.taskInfo(t.id),st=D.status(i);return '<button class="task '+(selected===t.id?'selected':'')+'" data-task="'+t.id+'"><div class="task-body">'+(i.photo?'<img src="'+esc(i.photo)+'" alt="'+esc(t.name)+'">':'<span class="task-no-thumb">'+(i.confirmed?'✓':'—')+'</span>')+'<div><div class="task-id">ID '+t.id+'</div><div class="task-name">'+esc(t.name)+'</div><div class="task-kind">'+A.categories[A.category(t)]+'</div></div></div><div class="task-bottom"><span class="tag '+st.tone+'">'+st.label+'</span><span class="task-date">'+t.start.slice(5).replace('-','.')+' – '+t.originalFinish.slice(5).replace('-','.')+'</span></div></button>';}).join('')+'</div>';
    queue.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const scroll=queue.scrollTop;selected=b.dataset.task;render();$('.queue').scrollTop=scroll;});queue.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{scope=b.dataset.scope;tagFilter=scope==='completed'?'confirmed':'all';render();});
    queue.querySelector('.queue-filter').textContent='상태 태그를 선택하면 해당 작업만 표시합니다.';
    if(tagFilter==='all'){const list=$('#task-list'),cards=[...list.children],groupOrder=['request','observation','extension','late','planned','confirmed','rejected','observed','accepted','pending'];list.replaceChildren();for(const key of groupOrder){const groupCards=cards.filter(card=>D.status(A.taskInfo(card.dataset.task)).key===key);if(!groupCards.length)continue;const section=document.createElement('section');section.className='task-status-group';section.dataset.statusGroup=key;const def=definitions.find(d=>d[0]===key),head=document.createElement('div');head.className='task-status-heading';head.innerHTML='<span class="tag '+def[2]+'">'+def[1]+'</span><small>'+groupCards.length+'건</small>';section.append(head,...groupCards);list.append(section);}}
    const info=A.taskInfo(selected),st=D.status(info),sub=info.sub,r=info.review,p=window.DEMO_DATA.photos;
    const filters=document.querySelector('.summary');filters.classList.add('review-filters');filters.setAttribute('aria-label','작업 상태별 필터');filters.innerHTML=definitions.filter(([key])=>counts[key]||['all','request','confirmed','planned','observation','extension','rejected'].includes(key)).map(([key,label,tone])=>'<button class="status-filter '+tone+' '+(tagFilter===key?'active':'')+'" data-filter="'+key+'" aria-pressed="'+(tagFilter===key)+'" '+(!counts[key]?'disabled':'')+'>'+label+'<span>'+counts[key]+'</span></button>').join('');filters.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{tagFilter=b.dataset.filter;render();});
    let body='<div class="detail-head"><h2>'+esc(info.task.name)+'</h2><span class="tag '+st.tone+'">'+st.label+'</span></div><div class="detail-sub">ID '+selected+' · 계획 '+info.task.start.slice(5).replace('-','.')+' – '+info.task.originalFinish.slice(5).replace('-','.')+' · '+(info.confirmed?'완료 이력 열람':selected==='45'?'AI 관측 검토':'현장 증빙 검토')+'</div>';
    if(r?.reason)body+='<section class="review-return" id="rejection-reason"><div class="review-return-head"><strong>반려 사유</strong><span>본사 · '+D.short(r.reviewedAt)+'</span></div>'+esc(r.reason)+'</section>';
    if(selected==='45'){
      body+='<div class="photo-tabs"><button id="analysis-view-tab" class="'+(wallView==='analysis'?'active':'')+'">원본·분석 결과</button><button id="timeline-view-tab" class="'+(wallView==='timeline'?'active':'')+'">사진 비교</button></div><div class="photo-grid analysis">'+(wallView==='analysis'?photo(p.wallAfter,'원본 · 분석 적용 전','original-photo')+photo(p.wallOverlay,'분석 화면 예시 · 동일 이미지','overlay-photo'):photo(p.wallBefore,'기준 사진 · 참고','baseline-photo')+photo(p.wallAfter,'분석 예시 사진','latest-photo'))+'</div><div class="metrics"><div class="metric"><div class="metric-label">왼쪽 벽 W01 · 설치 관측률</div><div class="metric-value numeric">78.50%</div></div><div class="metric"><div class="metric-label">오른쪽 벽 W02 · 설치 관측률</div><div class="metric-value numeric">82.00%</div></div></div><p class="detail-note">설치 ÷ (설치 + 미설치), 인식 불가 제외 · 관측 결과 수락과 완료 확인은 구분합니다.</p>';
    }else if(selected==='40')body+='<div class="photo-grid">'+photo(p.counterBefore,'02.15 착수 전 참고')+photo(info.photo,'02.18 골조 설치 완료')+'</div>';
    else if(info.photo)body+='<div class="photo-grid single">'+photo(info.photo,(info.examplePhoto?'공종별 참고 사진 · 실제 증빙 아님':info.confirmed?'완료 증빙':'최근 제출 사진')+(sub?' · '+sub.attempt+'차':''))+'</div>';
    else body+='<div class="review-no-photo">'+(info.confirmed?'완료 확인 이력이 있습니다. 이 시연에는 해당 작업의 사진을 연결하지 않았습니다.':'아직 제출된 사진이 없습니다. 일정과 현재 이력부터 확인할 수 있습니다.')+'</div>';
    if(sub)body+='<div class="report-text"><span>현장 담당자 보고</span><p>'+esc(sub.report)+'</p></div>';
    body+=D.facts(info);
    if(info.extension)body+='<section class="extension-review">'+U.extensionHTML(selected)+'</section>';
    if(!info.confirmed&&r&&['pending','request','rejected'].includes(r.state)&&!info.extension)body+='<div class="actions"><span class="action-note">사진과 작업 내용을 확인하고 처리합니다.</span><div class="buttons"><button class="secondary" id="reject">반려</button><button class="'+(selected==='45'?'primary':'confirm-button')+'" id="accept">'+(selected==='45'?'관측 결과 수락':sub?.completed?'완료 확인':'제출 내용 수락')+'</button></div></div>';
    body+='<section class="review-history"><div class="review-history-head"><h3>최근 작업·검토 이력</h3><button class="secondary" id="all-history">전체 이력 보기 →</button></div>'+D.timeline(info,3,true)+'</section>';
    $('#detail').innerHTML=body;
    if($('#accept'))$('#accept').onclick=()=>U.attempt(()=>{A.accept(selected);if(tagFilter!=='all')tagFilter=D.status(A.taskInfo(selected)).key;render();U.toast(selected==='45'?'관측 결과를 수락했습니다. 작업 완료와는 구분합니다.':'본사에서 완료를 확인했습니다.');});if($('#reject'))$('#reject').onclick=()=>U.reasonDialog('증빙 반려',reason=>{A.reject(selected,reason);if(tagFilter!=='all')tagFilter='rejected';render();});
    if(selected==='45'){$('#analysis-view-tab').onclick=()=>{wallView='analysis';render();};$('#timeline-view-tab').onclick=()=>{wallView='timeline';render();};}
    U.bindExtension($('#detail'),render);$('#all-history').onclick=()=>U.history(selected);document.querySelector('.footer a').href='02-field-submission.html?task='+selected;U.badges();
  };
  $('#review-week').onchange=()=>render();render();
})();
